import os,re
root='AlgebraicJacobian'
files=set()
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'): files.add(os.path.join(dp,f))
def mod2path(m): return m.replace('.','/')+'.lean'
def imports(p):
    out=[]
    try: txt=open(p).read()
    except: return out
    for line in txt.splitlines():
        s=line.strip()
        if s.startswith('import '):
            out.append(s.split()[1])
    return out
seen=set(); stack=[]
top=imports('AlgebraicJacobian.lean')
print("root import lines:",len(top))
for m in top:
    p=mod2path(m)
    if p in files: stack.append(p)
while stack:
    p=stack.pop()
    if p in seen: continue
    seen.add(p)
    for m in imports(p):
        q=mod2path(m)
        if q in files and q not in seen: stack.append(q)
print("on disk:",len(files),"reachable:",len(seen),"unrooted:",len(files-seen))
EOF

